const activeDeptId = ref<string | number | null>(null)
let regionsInflight: Promise<void> | null = null
function loadRegions(): Promise<void> {
  if (regionsInflight) return regionsInflight
  regionsInflight = getPortalDeptRegionTree()
    .then(tree => {
      const tabs = flattenRegionTabs(tree || []).map(t => ({
        ...t,
        label: t.label === CITY_WIDE_LABEL ? REGION_ALL_LABEL : t.label,
      }))
      if (!tabs.length) { console.warn('[首页] 区域树为空，统计指标不请求、显示「—」'); regionTabs.value = []; activeDeptId.value = null; return }
      regionTabs.value = tabs
      const city = tabs.find(t => t.label === REGION_ALL_LABEL)
      activeDeptId.value = (city ?? tabs[0]).deptId
      loadStats()
    })
    .catch(() => { console.warn('[首页] 区域树加载失败'); regionTabs.value = []; activeDeptId.value = null })
    .finally(() => { regionsInflight = null })
  return regionsInflight
}
